INSERT INTO recipes (id, name_ja, name_en, description, servings, prep_time, cook_time, steps) VALUES
('okonomiyaki', 'お好み焼き', 'Okonomiyaki', 'キャベツたっぷりの大阪風お好み焼き。ソースとマヨネーズで仕上げる定番の家庭料理。', 2, 15, 20, '["キャベツを粗めに千切りにする。","ボウルに小麦粉、だし粉、水150mlを混ぜて生地を作る。","生地にキャベツと溶き卵を加えてさっくり混ぜる。","フライパンに油を熱し、生地を丸く流し入れ、豚バラを上に乗せる。","蓋をして中火で5分焼き、ひっくり返してさらに5分焼く。","焼き上がったらソースとマヨネーズをかける。","お好みで青のりとかつお節を散らして完成。"]'::jsonb),
('curry-rice', 'カレーライス', 'Japanese Curry Rice', '市販のルーを使った家庭の定番カレー。じっくり煮込んだコクのある味わい。', 4, 15, 40, '["白米を洗って炊飯器または鍋で炊く。","鶏肉をひと口大に切り、じゃがいも・にんじんは乱切り、玉ねぎはくし形に切る。","鍋に油を熱して玉ねぎを炒め、しんなりしたら鶏肉を加えて表面に焼き色をつける。","じゃがいもとにんじんを加えて2〜3分炒める。","水700mlを加えて中火で煮立てたらアクを取り除く。","弱火にして蓋をして20分煮る。","火を止めてカレールーを割り入れ、溶けたら再び弱火で10分煮る。","ご飯を盛ったお皿にカレーをかけて完成。"]'::jsonb),
('teriyaki-chicken', '照り焼きチキン', 'Teriyaki Chicken', '甘辛タレが絡んだ照り焼きチキン。ご飯が進む定番おかず。', 2, 10, 15, '["鶏もも肉の厚い部分に切り込みを入れて均一な厚さにする。","醤油・みりん・砂糖・酒を混ぜてタレを作る。","フライパンに油を熱し、鶏肉を皮目を下にして中火で焼く。","3〜4分焼いてきれいな焼き色がついたらひっくり返す。","蓋をして弱火で5分蒸し焼きにする。","タレを回し入れ、強火で絡めながらとろみがつくまで煮詰める。","食べやすい大きさに切り、ごまをかけて完成。"]'::jsonb),
('miso-soup', '味噌汁', 'Miso Soup', '豆腐とわかめの定番味噌汁。毎日の食卓に欠かせない一品。', 2, 5, 10, '["わかめを水で戻しておく（5分程度）。","鍋に水400mlとだし粉を入れて中火にかける。","沸騰したら豆腐を1cm角に切って加える。","再沸騰したら火を弱め、戻したわかめを加える。","火を止め、味噌を溶き入れる（沸騰させない）。","お椀に注ぎ、小口切りにしたねぎを散らして完成。"]'::jsonb),
('oyakodon', '親子丼', 'Oyakodon', '鶏肉と卵を甘辛だしで煮てご飯に乗せた丼。ふわとろ卵がポイント。', 2, 10, 15, '["白米を炊いておく。","鶏肉をひと口大に切り、玉ねぎは薄切りにする。","小鍋に水100ml・醤油・みりん・砂糖・だし粉を入れて中火で煮立てる。","玉ねぎを加えて2分煮たら鶏肉を加え、火が通るまで煮る（3〜4分）。","溶き卵を回し入れ、蓋をして弱火で30秒〜1分蒸らす（半熟がベスト）。","どんぶりにご飯を盛り、鶏卵をそっと乗せて完成。"]'::jsonb),
('nikujaga', '肉じゃが', 'Nikujaga', 'じゃがいもと牛肉を甘辛く煮た日本の家庭料理の代表格。ほっとする懐かしい味。', 4, 15, 30, '["じゃがいもを乱切り、にんじんも乱切り、玉ねぎはくし形に切る。","鍋に油を熱し、牛肉を炒める。色が変わったら野菜を加えてさらに炒める。","水300mlとだし粉を加えて中火で煮立てる。","アクを取り除いたら醤油・みりん・砂糖を加える。","落とし蓋をして弱火で20分煮る。","じゃがいもが柔らかくなったら完成。"]'::jsonb),
('karaage', '唐揚げ', 'Karaage Fried Chicken', 'にんにくと醤油で下味をつけたサクサクの揚げ鶏。ビールに合う定番おつまみ。', 2, 20, 15, '["鶏もも肉をひと口大に切る。","ポリ袋に醤油・酒・すりおろしにんにく・すりおろし生姜を入れ、鶏肉を加えて揉み込む。","15分以上漬け込む（時間があれば30分〜1時間）。","揚げ油を170〜180°Cに熱する。","鶏肉の汁気を切り、片栗粉をまぶす。","揚げ油に入れて3〜4分揚げ、一度取り出して1分休ませる。","再度180°Cで30秒〜1分揚げてカリッとさせる。","皿に盛り、レモンを添えて完成。"]'::jsonb),
('ramen', 'ラーメン', 'Ramen (Home Style)', '市販のスープを使った手軽な家庭ラーメン。チャーシューと煮卵でワンランクアップ。', 2, 15, 20, '["豚バラ肉を丸めてタコ糸で縛り、醤油・みりん・酒でチャーシューを作る。","煮卵を作る：卵を7分茹でて殻を剥き、醤油・みりん・砂糖の漬け液に1時間漬ける。","鍋に水600ml・鶏ガラスープ素・醤油・すりおろしにんにく・すりおろし生姜を入れて中火で煮立てる。","別の鍋でラーメン麺を袋の表示通りに茹でる。","もやしをさっと茹でる。","器にスープを盛り、水気を切った麺を入れる。","チャーシュー・煮卵・もやし・長ねぎ・海苔を乗せ、ごま油を垂らして完成。"]'::jsonb)
